import json,socket,subprocess,copy,sys,time
from pathlib import Path
session='codex-browser-integration';app=sys.argv[1];out=Path(sys.argv[2]);out.mkdir(parents=True,exist_ok=True)
env=json.loads(Path('/var/tmp/olo-dev/'+session+'/env.json').read_text())
def ask(path,r):
 with socket.socket(socket.AF_UNIX) as s:
  s.settimeout(5);s.connect(path);s.sendall((json.dumps(r)+'\n').encode());return json.loads(s.makefile().readline())
def ipc(r):return ask(env['OLO_SOCKET'],r)
def win():return next(w for w in ipc({'type':'list_windows'})['windows'] if w['app_id']==app)
def review(w):return ask(f'/run/user/1000/olo-menus-{w["pid"]}.sock',{'review':True})
original=ipc({'type':'get_settings'})['settings'];rows=[]
try:
 for mode in ['light','dark','night']:
  for scale in [1,1.25,1.5,1.75,2]:
   cfg=copy.deepcopy(original);cfg['appearance']['theme']='dark' if mode=='night' else mode;cfg['appearance']['night_light']['mode']='on' if mode=='night' else 'off';cfg['appearance']['night_light']['temperature']=4500;cfg['display']['scale']=scale
   for o in cfg['display'].get('outputs',{}).values():o.pop('scale',None)
   ipc({'type':'set_settings','settings':cfg});w=win();frame={'x':49,'y':40,'width':690,'height':400};ipc({'type':'place','id':w['id'],'frame':frame})
   prev=None
   for _ in range(50):
    r=review(w)
    if r==prev and r and abs(r[0]['scale']-scale)<.01:break
    prev=r;time.sleep(.1)
   w=win();f=w['frame']
   subprocess.run(['/usr/bin/python3','tools/dev/tsession','shot',session,str(out/f'{mode}-{scale}.png'),*[str(f[k]) for k in ['x','y','width','height']]],check=True,stdout=subprocess.DEVNULL)
   rows.append(dict(mode=mode,scale=scale,window=w,review=r))
finally:ipc({'type':'set_settings','settings':original})
(out/'review.json').write_text(json.dumps(rows,indent=2));print([(r['mode'],r['scale'],len(r['review'][0]['findings'])) for r in rows])
